begin;
update tb_m1_info_customer set img_src_gum = admin_no || '_gum.JPEG' where 1=1
update tb_m1_info_customer set img_src_af = admin_no || '_af.JPEG' where 1=1
update tb_m1_info_customer set img_src_bf = admin_no || '_bf.JPEG' where 1=1
update tb_m1_info_customer set img_src_add = admin_no || '_add.JPEG' where 1=1
commit;

/* deleteCustomerInfo 수용가 삭제*/ begin;
insert into tb_delete_cust_his( point_sq, blk_sq, site_sq, use_cd, ins_dt, cust_sq, admin_no, cust_name, dev_no, sub_dev_no, access_key ) select a.point_sq, a.blk_sq, a.site_sq, a.use_cd, now(), a.cust_sq , a.admin_id , a.cust_nm , COALESCE(a.dev_no, '알수없음') , COALESCE(a.sub_dev_no,'알수없음') , #{acKey} from vi_m1_sv_point_list a where 1=1 and point_sq = #{pointSq};
delete from tb_m1_cmap_device where 1=1 and point_sq = #{pointSq}; delete from tb_m1_info_point where 1=1 and point_sq = #{pointSq}; delete from tb_m1_info_customer where 1=1 and cust_sq = #{custSq};
commit;

      /* updateCustomerInfo  수용가 간단수정*/
      begin;

      update tb_m1_info_customer set
        cust_name  = #{custNm}
      where
        cust_sq = #{custSq}::integer;


      update tb_m1_cmap_device
        set dev_no = #{devNo}
          , sub_dev_no = #{subDevNo}
      where 1=1 
        and point_sq = #{pointSq}::integer;
        
      commit;

/*insertsiteSq*/
  update tb_m1_info_site
     set site_nm = #{site_nm}
        ,scco_cd = #{scco_cd}
   where 1=1
     and site_sq = #{site_sq}

/*insertsiteSq*/
  update tb_m1_info_company
     set company_nm = #{company_nm}
        ,company_cd = #{company_cd}
   where 1=1
     and company_sq = #{company_sq}
